#!/usr/bin/env bash
# teardown_linux_netns.sh - Generated by PS-007
# Run with: sudo bash teardown_linux_netns.sh

echo '[-] Removing bridge br-iot0...'
ip link set br-iot0 down 2>/dev/null || true
ip link delete br-iot0 type bridge 2>/dev/null || true

ip netns delete ns-mon 2>/dev/null || true
ip netns delete ns-iot1 2>/dev/null || true
ip netns delete ns-iot2 2>/dev/null || true
ip netns delete ns-iot3 2>/dev/null || true
ip netns delete ns-iot4 2>/dev/null || true
ip netns delete ns-iot5 2>/dev/null || true
ip netns delete ns-attacker 2>/dev/null || true
echo '[+] All namespaces and bridges removed.'
